import { Card } from "@/components/ui/card";
import { Avatar, AvatarImage, AvatarFallback } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { useRouter } from "next/navigation";
import { Star } from "lucide-react";

export default function DoctorCard({ doctor, onAction, actionLabel = "Book Now" }) {
  const router = useRouter();
  const handleViewProfile = () => {
    router.push(`/doctors/${doctor._id || doctor.id}`);
  };

  // Render rating as stars (max 5)
  const renderStars = (rating = 0) => {
    const stars = [];
    for (let i = 1; i <= 5; i++) {
      stars.push(
        <Star
          key={i}
          size={18}
          className={
            i <= Math.round(rating)
              ? "text-yellow-400 inline-block"
              : "text-gray-300 inline-block"
          }
          fill={i <= Math.round(rating) ? "#facc15" : "none"}
        />
      );
    }
    return stars;
  };

  return (
    <Card className="rounded-xl shadow hover:bg-gray-50 flex flex-col gap-4 items-center p-5 transition w-full max-w-xs mx-auto">
      <Avatar className="w-16 h-16">
        <AvatarImage
          src={
            doctor?.avatarUrl
              ? `http://localhost:5000${doctor.avatarUrl}`
              : "/default-avatar.png"
          }
          alt={doctor?.fullName || "Doctor Avatar"}
          onError={(e) => {
            e.currentTarget.src = "/default-avatar.png";
          }}
        />
        <AvatarFallback>
          {doctor?.fullName?.[0] || "U"}
        </AvatarFallback>
      </Avatar>
      <div className="text-lg font-semibold text-gray-800 text-center">{doctor.fullName}</div>
      <Badge className="bg-blue-100 text-blue-700 mb-1">{doctor.specialization}</Badge>
      <div className="text-gray-500 text-xs">{doctor.experience} yrs experience</div>
      <div className="flex items-center gap-1 mt-1">{renderStars(doctor.rating)}
        <span className="ml-1 text-xs text-gray-500">{doctor.rating?.toFixed(1) || "-"}</span>
      </div>
      <Separator className="my-2" />
      <div className="flex gap-2 w-full">
        <Button
          variant="outline"
          className="flex-1"
          onClick={handleViewProfile}
        >
          View Profile
        </Button>
        <Button
          className="flex-1"
          onClick={() => onAction?.(doctor)}
        >
          {actionLabel}
        </Button>
      </div>
    </Card>
  );
} 